#!/usr/bin/env bash
# Tests for trace.sh. Usage: bash .github/scripts/trace.test.sh
# Builds a made-up tree with a complete chain, a chain with no QA record and a chain with
# no acceptance, runs trace.sh and compares docs/traceability.md with the expected text.
set -uo pipefail

here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cd "$work" || exit 2
mkdir -p docs/specs docs/qa docs/acceptance docs/intents
failed=0

spec() { # $1 file, $2 ticket, $3 number of requirements
  { printf '# Design\n\nIntent: docs/intents/%s.md (A)\nTicket: %s\n\n## Requirements\n' "$1" "$2"
    local i; for i in $(seq 1 "$3"); do printf -- '- R%s. Something %s.\n' "$i" "$i"; done
    printf '\n## Design\nNone.\n'; } > "docs/specs/$1.md"
  printf '# Intent\n' > "docs/intents/$1.md"
}
qa() { # $1 key, $2 spec, then rows "ID|Requirement|Result", last arg "-" or a Not covered text
  local k="$1" s="$2"; shift 2
  { printf '# QA record: %s\nTicket: %s\nSpec: docs/specs/%s.md\nVersion: v\nEnvironment: e\n\n## Test matrix\n' "$k" "$k" "$s"
    printf '| ID | Requirement | Layer | Steps | Expected | Evidence | Priority | Approved | Result | Run |\n|---|---|---|---|---|---|---|---|---|---|\n'
    local r id rq rs
    for r in "$@"; do
      IFS='|' read -r id rq rs <<< "$r"
      printf '| %s | %s | command | s | 3 lines | f | P1 | QA Ann, 2026-11-25 | %s | QA Ann, 2026-11-25 |\n' "$id" "$rq" "$rs"
    done; } > "docs/qa/$k.md"
}
acc() { # $1 slug, $2 outcome, $3 tickets, $4 verdict
  printf '# Acceptance\nOutcome: %s\nMilestone: M9\nTickets: %s\n\n## Success Criteria\n- SC1. x\n\n## Confirmed\nBA Bea, 2026-11-24\n\n## Results\n| SC | Tickets | Evidence | Verdict | Reason |\n|---|---|---|---|---|\n\n## Verdict\n%s\nBy: BA, Bea\n' "$2" "$3" "$4" > "docs/acceptance/$1.md"
}

spec a 'TOKI-900' 2
spec b 'TOKI-901' 1
spec c 'TOKI-902' 3
spec d 'TOKI-903' 1
printf '# no ticket here\n\n## Requirements\n- R1. x\n' > docs/specs/e.md
qa TOKI-900 a "T1|R1|Pass" "T2|R2|Pass"
qa TOKI-902 c "T1|R1|Pass" "T2|R2|Fail"
printf '\n## Not covered\n- R3. Dropped.\n' >> docs/qa/TOKI-902.md
qa TOKI-903 d "T1|R1|Pass"
acc out I99 "TOKI-900, TOKI-901" Pending
acc done I98 "TOKI-903" Accepted
printf '# Milestone\nMilestone: M9\nOutcomes: out, done\n' > docs/acceptance/milestone-m9.md

cat > expected.md <<'EXP'
# Traceability

Generated by `.github/scripts/trace.sh` from the records in `docs/`. Do not edit by hand.

| Outcome | Intent | Spec | Ticket | Requirements | Rows passed | Acceptance |
| --- | --- | --- | --- | --- | --- | --- |
| I99 | docs/intents/a.md | docs/specs/a.md | TOKI-900 | 2/2 | 2/2 | Pending (out) |
| I99 | docs/intents/b.md | docs/specs/b.md | TOKI-901 | no QA record | no QA record | Pending (out) |
| - | docs/intents/c.md | docs/specs/c.md | TOKI-902 | 3/3 | 1/2 | no acceptance |
| I98 | docs/intents/d.md | docs/specs/d.md | TOKI-903 | 1/1 | 1/1 | Accepted (done) |
EXP

bash "$here/trace.sh" > /dev/null 2>&1; rc=$?
if [ "$rc" -ne 0 ]; then echo "FAIL run: exit $rc"; failed=$((failed + 1)); fi
if diff -u expected.md docs/traceability.md; then echo "ok   output matches"; else echo "FAIL output differs"; failed=$((failed + 1)); fi
cp docs/traceability.md first.md
bash "$here/trace.sh" > /dev/null 2>&1
if cmp -s first.md docs/traceability.md; then echo "ok   rerun gives the same file"; else echo "FAIL rerun differs"; failed=$((failed + 1)); fi

# a tree with no specs
empty=$(mktemp -d); mkdir -p "$empty/docs"
( cd "$empty" && bash "$here/trace.sh" >/dev/null 2>&1 ); rc=$?
rm -rf "$empty"
if [ "$rc" -eq 2 ]; then echo "ok   no docs/specs"; else echo "FAIL no docs/specs: exit $rc, expected 2"; failed=$((failed + 1)); fi

[ "$failed" -eq 0 ] && echo "all passed"
[ "$failed" -eq 0 ]
